## @cvxpy test_grad.py
##
## Atom-level gradient (subgradient) parity with CVXPY's Atom._grad and
## Atom.grad chain-rule walker. Expected diagonal values are pinned to the
## CVXPY-derived numerics generated by scripts/cvxpy_grad_expected.py;
## tolerance is 1e-10 because both sides compute closed-form math.

library(testthat)
library(CVXR)

## ---------------------------------------------------------------------
## Helpers
## ---------------------------------------------------------------------

.diag_of_grad <- function(expr) {
  ## Returns the diagonal of the (single-variable) Jacobian, or NULL if
  ## the gradient is undefined.
  g <- grad(expr)
  if (length(g) == 0L) {
    return(NULL)
  }
  m <- g[[1L]]
  if (is.null(m)) {
    return(NULL)
  }
  diag(as.matrix(m))
}

.set_value <- function(x, v) {
  value(x) <- matrix(as.numeric(v), nrow = length(v), ncol = 1L)
  x
}

## ---------------------------------------------------------------------
## Walker behaviour (no CVXPY counterpart — defensive R-level invariants)
## ---------------------------------------------------------------------

## @cvxpy NONE
test_that("grad walker: Variable returns identity keyed by id", {
  x <- Variable(3)
  g <- grad(x)
  expect_length(g, 1L)
  expect_true(as.character(x@id) %in% names(g))
  expect_equal(diag(as.matrix(g[[1L]])), c(1, 1, 1))
})

## @cvxpy NONE
test_that("grad walker: Constant has empty grad", {
  expect_length(grad(Constant(5)), 0L)
})

## @cvxpy NONE
test_that("grad walker: missing arg value propagates NULL through .error_grad", {
  x <- Variable(3)  # value() is NULL
  e <- abs(x)
  g <- grad(e)
  ## Variable has one entry; walker propagates NULL through .error_grad.
  expect_true(as.character(x@id) %in% names(g))
  expect_null(g[[as.character(x@id)]])
})

## NOTE: After AffAtom .grad lands in batch 6, every atom in CVXR has a
## registered .grad or .column_grad (real or NULL stub mirroring CVXPY's
## NotImplementedError). The previous "abstract error sentinel" test
## (which kept getting retargeted batch-by-batch) is removed: the
## abstract method(.grad, Atom) and method(.column_grad, Atom) defaults
## still exist in atoms/atom.R as a defensive backstop for any newly-
## added atom that forgets a hook, but exercising them via a real atom
## now requires constructing a brand-new unregistered subclass which
## isn't worth the test scaffolding.

## ---------------------------------------------------------------------
## .grad(AffAtom): per-atom hook for affine atoms (the long-pole port)
## ---------------------------------------------------------------------

## @cvxpy test_grad.py::TestSingleVarAtomGradients::test_single_var_atom[transpose]
test_that(".grad(AffAtom): transpose gives the right permutation", {
  X <- Variable(c(2, 3))
  value(X) <- matrix(seq_len(6), 2, 3)
  g <- grad(t(X))
  expected <- matrix(0, 6, 6)
  ## d(vec(X^T))[j] / d(vec(X))[i] = 1 iff (i, j) maps via transpose.
  ## Same numbers as CVXPY's reference (verified bit-exactly).
  expected[1, 1] <- 1; expected[2, 4] <- 1; expected[3, 2] <- 1
  expected[4, 5] <- 1; expected[5, 3] <- 1; expected[6, 6] <- 1
  expect_equal(as.matrix(g[[1L]]), expected, tolerance = 1e-10)
})

## @cvxpy test_grad.py::TestSingleVarAtomGradients::test_single_var_atom[sum]
test_that(".grad(AffAtom): sum_entries gives all-ones column", {
  x <- .set_value(Variable(3), c(1, 2, 3))
  g <- grad(sum_entries(x))
  expect_equal(as.numeric(g[[1L]]), c(1, 1, 1), tolerance = 1e-10)
})

## @cvxpy test_grad.py::TestSingleVarAtomGradients::test_single_var_atom[reshape]
test_that(".grad(AffAtom): reshape (column-major) is identity", {
  X <- Variable(c(2, 3))
  value(X) <- matrix(seq_len(6), 2, 3)
  g <- grad(reshape_expr(X, c(3, 2)))
  expect_equal(as.matrix(g[[1L]]), diag(6), tolerance = 1e-10)
})

## @cvxpy NONE -- chain rule through transpose
test_that("Chain rule: grad(sum(t(X))) is all-ones", {
  X <- Variable(c(2, 3))
  value(X) <- matrix(seq_len(6), 2, 3)
  g <- grad(sum_entries(t(X)))
  expect_equal(as.numeric(g[[1L]]), rep(1, 6), tolerance = 1e-10)
})

## @cvxpy NONE -- chain rule through transpose + abs (sign-permutation)
test_that("Chain rule: grad(t(abs(X))) gives sign-permutation", {
  X <- Variable(c(2, 2))
  value(X) <- matrix(c(-1, 2, -3, 4), 2, 2)
  g <- grad(t(abs(X)))
  ## abs gives sign-diagonal in vec(X) order; t permutes; chain composes.
  ## CVXR convention: row i col j = d(output[j])/d(input[i]); composes as
  ## diag(sign(vec(X))) %*% perm(transpose).
  expected <- matrix(0, 4, 4)
  v <- c(-1, 2, -3, 4)
  signs <- sign(v)
  ## Output entries are vec(t(abs(X))) in column-major.
  ## abs(X) = ((1,2),(3,4)); t(abs(X)) = ((1,3),(2,4)); vec = (1,2,3,4).
  ## Permutation: out[1]=in[1], out[2]=in[3], out[3]=in[2], out[4]=in[4].
  ## Then sign-scale per input position.
  expected[1, 1] <- signs[1]
  expected[3, 2] <- signs[3]
  expected[2, 3] <- signs[2]
  expected[4, 4] <- signs[4]
  expect_equal(as.matrix(g[[1L]]), expected, tolerance = 1e-10)
})

