## @cvxpy test_grad.py::TestSingleVarAtomGradients::test_single_var_atom[logistic]
test_that("Logistic: sigmoid(x) = 1 / (1 + exp(-x)), numerically stable", {
  x <- .set_value(Variable(3), c(-1, 0, 2))
  expect_equal(.diag_of_grad(logistic(x)),
               c(0.2689414214, 0.5, 0.880797078), tolerance = 1e-7)

  ## Stability check: x = 10 must not overflow; x = -10 must not vanish to 0.
  x <- .set_value(Variable(3), c(10, -10, 0))
  expect_equal(.diag_of_grad(logistic(x)),
               c(0.9999546021, 4.53978687e-05, 0.5), tolerance = 1e-9)
})

