## @cvxpy test_grad.py::TestMultiVarAtomGradients::test_multi_var_atom[maximum]
test_that("Maximum: indicator-of-max with first-arg-wins tie break", {
  ## x = (1, 2, 0.5); y = (0.5, 3, 0.5) — tie at idx 3, x wins.
  x <- .set_value(Variable(3), c(1.0, 2.0, 0.5))
  y <- .set_value(Variable(3), c(0.5, 3.0, 0.5))
  g <- grad(max_elemwise(x, y))
  expect_equal(diag(as.matrix(g[[as.character(x@id)]])),
               c(1, 0, 1), tolerance = 1e-10)
  expect_equal(diag(as.matrix(g[[as.character(y@id)]])),
               c(0, 1, 0), tolerance = 1e-10)
})

## @cvxpy test_grad.py::TestMultiVarAtomGradients::test_multi_var_atom[minimum]
test_that("Minimum: indicator-of-min with first-arg-wins tie break", {
  x <- .set_value(Variable(3), c(1.0, 2.0, 0.5))
  y <- .set_value(Variable(3), c(0.5, 3.0, 0.5))
  g <- grad(min_elemwise(x, y))
  expect_equal(diag(as.matrix(g[[as.character(x@id)]])),
               c(0, 1, 1), tolerance = 1e-10)
  expect_equal(diag(as.matrix(g[[as.character(y@id)]])),
               c(1, 0, 0), tolerance = 1e-10)
})

## @cvxpy test_grad.py::TestMultiVarAtomGradients::test_multi_var_atom[kl_div]
test_that("KL divergence: d/dx = log(x/y), d/dy = 1 - x/y", {
  x <- .set_value(Variable(3), c(1.0, 2.0, 0.5))
  y <- .set_value(Variable(3), c(0.5, 1.0, 1.0))
  g <- grad(kl_div(x, y))
  expect_equal(diag(as.matrix(g[[as.character(x@id)]])),
               c(0.6931471806, 0.6931471806, -0.6931471806), tolerance = 1e-7)
  expect_equal(diag(as.matrix(g[[as.character(y@id)]])),
               c(-1, -1, 0.5), tolerance = 1e-10)
})

## @cvxpy test_grad.py::TestMultiVarAtomGradients::test_multi_var_atom[kl_div]
test_that("KL divergence: NULL when either arg has a non-positive entry", {
  x <- .set_value(Variable(3), c(0.0, 1.0, 2.0))
  y <- .set_value(Variable(3), c(1.0, 1.0, 1.0))
  g <- grad(kl_div(x, y))
  expect_null(g[[as.character(x@id)]])
  expect_null(g[[as.character(y@id)]])

  x <- .set_value(Variable(3), c(1.0, 2.0, 3.0))
  y <- .set_value(Variable(3), c(0.0, 1.0, 1.0))
  g <- grad(kl_div(x, y))
  expect_null(g[[as.character(x@id)]])
  expect_null(g[[as.character(y@id)]])
})

## @cvxpy test_grad.py::TestMultiVarAtomGradients::test_multi_var_atom[rel_entr]
test_that("Relative entropy: d/dx = log(x/y) + 1, d/dy = -x/y", {
  x <- .set_value(Variable(3), c(1.0, 2.0, 0.5))
  y <- .set_value(Variable(3), c(0.5, 1.0, 1.0))
  g <- grad(rel_entr(x, y))
  expect_equal(diag(as.matrix(g[[as.character(x@id)]])),
               c(1.693147181, 1.693147181, 0.3068528194), tolerance = 1e-7)
  expect_equal(diag(as.matrix(g[[as.character(y@id)]])),
               c(-2, -2, -0.5), tolerance = 1e-10)
})

## @cvxpy test_grad.py::TestSingleVarAtomGradients::test_single_var_atom[huber]
test_that("Huber(M=1): 2 * sign(x) * min(|x|, 1)", {
  x <- .set_value(Variable(3), c(-2.0, 0.5, 3.0))
  ## At x=-2: |x|>M, so grad = 2*sign(-2)*1 = -2.
  ## At x=0.5: |x|<M, so grad = 2*0.5 = 1.
  ## At x=3: |x|>M, so grad = 2*1 = 2.
  expect_equal(.diag_of_grad(huber(x, M = 1)),
               c(-2, 1, 2), tolerance = 1e-10)
})

## @cvxpy test_grad.py::TestSingleVarAtomGradients::test_single_var_atom[huber_M2]
test_that("Huber(M=2): scales the linear-region slope", {
  x <- .set_value(Variable(3), c(-2.0, 0.5, 3.0))
  ## At x=-2: |x|=M, grad = 2*sign(-2)*2 = -4.
  ## At x=0.5: |x|<M, grad = 2*0.5 = 1.
  ## At x=3: |x|>M, grad = 2*1*2 = 4.
  expect_equal(.diag_of_grad(huber(x, M = 2)),
               c(-4, 1, 4), tolerance = 1e-10)
})

