## @cvxpy test_grad.py::TestSingleVarAtomGradients::test_single_var_atom[log_det]
test_that("LogDet: X^{-T} on the open PSD cone; NULL on the boundary", {
  Y <- Variable(c(3, 3), symmetric = TRUE)
  P <- matrix(c(2, 0.5, 0,  0.5, 2, 0.5,  0, 0.5, 2), 3, 3, byrow = TRUE)
  value(Y) <- P
  g <- grad(log_det(Y))
  expected <- c(0.5357142857, -0.1428571429, 0.03571428571,
                -0.1428571429, 0.5714285714, -0.1428571429,
                0.03571428571, -0.1428571429, 0.5357142857)
  expect_equal(as.numeric(g[[1L]]), expected, tolerance = 1e-7)

  ## Boundary: a singular matrix triggers the NULL path.
  P_sing <- matrix(c(1, 0, 0,  0, 0, 0,  0, 0, 1), 3, 3)
  value(Y) <- P_sing
  g_null <- grad(log_det(Y))
  expect_null(g_null[[as.character(Y@id)]])
})

